#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Paddle sandbox setup for spec #86 (#89 checkout page, #94 subscription).
#
#   bash scripts/paddle-sandbox-wizard.sh      (Git Bash on Windows; needs curl and node)
#
# Sandbox only; live is #97, which can follow the same stages against
# https://api.paddle.com with a live account. Re-running is safe: values already
# saved are offered as defaults, and the product, price and webhook destination
# are only created once.
#
# Every value lands in ENV_FILE, outside the repo. Never commit it or paste its
# values into issues or logs. How the code reads it:
#   Worker (wrangler dev): copy PADDLE_API_KEY, PADDLE_API_BASE_URL, PADDLE_PRICE_ID,
#     PADDLE_WEBHOOK_SECRET into the Worker's .dev.vars (gitignored).
#   Site (Astro dev): PADDLE_CLIENT_TOKEN and PADDLE_ENVIRONMENT go into the site's
#     .env.local as PUBLIC_PADDLE_CLIENT_TOKEN / PUBLIC_PADDLE_ENVIRONMENT.
#   Webhook tunnel: node scripts/paddle-tunnel.ts reads this file directly.
# ──────────────────────────────────────────────────────────────────────────

ENV_FILE="$HOME/.config/naruhodo/paddle-sandbox.env"
mkdir -p "$(dirname "$ENV_FILE")"

PADDLE_API_BASE_URL='https://sandbox-api.paddle.com'
SANDBOX_DASHBOARD='https://sandbox-vendors.paddle.com'
SITE_ORIGIN_LOCAL='http://localhost:4321'
WEBHOOK_PATH='/webhooks/paddle'
# API key permissions the Worker and this wizard need; stage 3 lists them and checks them with GET /.
PADDLE_PERMISSIONS=(transaction.write product.write price.write customer.write subscription.write
  notification_setting.write notification.read notification_simulation.write customer_portal_session.write)
WEBHOOK_EVENTS='["subscription.created","subscription.updated","subscription.activated","subscription.canceled","subscription.past_due","subscription.paused","subscription.resumed","transaction.completed","adjustment.updated"]'

# paddle_api METHOD PATH [JSON]: calls the sandbox API; sets HTTP_STATUS and RESPONSE.
# The key goes through a header file so it never shows up in the process list.
paddle_api() {
  local method="$1" path="$2" body="${3:-}" out hdr
  out=$(mktemp); hdr=$(mktemp)
  printf 'Authorization: Bearer %s\nContent-Type: application/json\n' "$PADDLE_API_KEY" > "$hdr"
  local args=(-sS -o "$out" -w '%{http_code}' -X "$method" -H "@$hdr")
  [[ -n "$body" ]] && args+=(--data "$body")
  HTTP_STATUS=$(curl "${args[@]}" "$PADDLE_API_BASE_URL$path") || HTTP_STATUS=000
  RESPONSE=$(cat "$out"); rm -f "$out" "$hdr"
}

# json_get EXPR: reads a field out of RESPONSE, e.g. json_get 'data.id'.
json_get() {
  printf '%s' "$RESPONSE" | node -e '
    let s = ""; process.stdin.on("data", d => s += d).on("end", () => {
      let v; try { v = new Function("o", "return o." + process.argv[1])(JSON.parse(s)); } catch { v = undefined; }
      process.stdout.write(v == null ? "" : String(v));
    });' "$1"
}

api_ok() { [[ "$HTTP_STATUS" =~ ^2 ]]; }
api_fail() {
  warn "Paddle API $1 failed (HTTP $HTTP_STATUS): $(json_get 'error.code') $(json_get 'error.detail')"
  exit 1
}

# missing_permissions: which PADDLE_PERMISSIONS the key lacks, space-separated, read from a
# GET / response in RESPONSE. Paddle's API root lists every permission of the key (including
# the read implied by each write) and changes nothing.
missing_permissions() {
  local granted=",$(json_get 'data.caller.permissions')," p missing=()
  for p in "${PADDLE_PERMISSIONS[@]}"; do [[ "$granted" == *",$p,"* ]] || missing+=("$p"); done
  printf '%s' "${missing[*]}"
}

find_cloudflared() {
  command -v cloudflared 2>/dev/null && return 0
  local p
  for p in "/c/Program Files (x86)/cloudflared/cloudflared.exe" "/c/Program Files/cloudflared/cloudflared.exe"; do
    [[ -x "$p" ]] && { printf '%s\n' "$p"; return 0; }
  done
  return 1
}

run_wizard() {

TOTAL_STAGES=10

for tool in curl node; do
  command -v "$tool" >/dev/null 2>&1 || { warn "需要 $tool，請先安裝"; exit 1; }
done

banner "Paddle sandbox 設定（spec #86）"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "註冊 Paddle sandbox 帳號"
say "sandbox 是跟正式帳號完全分開的測試帳號，產品、價格、key 都不互通。"
say "就算之後有正式帳號，sandbox 也要另外註冊。已經有的話直接登入即可。"
open_url "https://sandbox-login.paddle.com/signup"
step "用你的 email 註冊（或登入）並完成 email 驗證。"
step "看到 sandbox 後台（網址是 sandbox-vendors.paddle.com）就算完成。"
note "sandbox 不需要網域審核。"
pause "進到 sandbox 後台後按 Enter"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "產品網域"
say "default payment link 不能填 localhost，要一個真的網域（sandbox 不審核，"
say "網站還沒上線也沒關係）。只填網域本身，不要 https:// 也不要路徑。"
while :; do
  ask PRODUCT_DOMAIN "產品主網域（例如 example.com）："
  [[ "$PRODUCT_DOMAIN" =~ ^[a-z0-9.-]+\.[a-z]{2,}$ ]] && break
  warn "看起來不像網域，請再輸入一次"
done
write_env PRODUCT_DOMAIN "$PRODUCT_DOMAIN"
write_env PADDLE_ENVIRONMENT "sandbox"
write_env PADDLE_API_BASE_URL "$PADDLE_API_BASE_URL"
write_env SITE_ORIGIN_LOCAL "$SITE_ORIGIN_LOCAL"
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "server 用的 API key"
say "Worker 用這把 key 呼叫 Paddle API；這個 wizard 接下來也用它建立產品與 webhook。"
open_url "$SANDBOX_DASHBOARD/settings/authentication"
step "點「API keys」分頁 → 「New API key」。"
step "Name：naruhodo-local-dev；Description：本機 wrangler dev 用。"
step "Permissions 勾這幾個（write 都包含 read）："
note "    transaction.write、product.write、price.write、customer.write、"
note "    subscription.write、notification_setting.write、notification.read、"
note "    notification_simulation.write、customer_portal_session.write"
note "    （最後這個在畫面上是 Customer portal sessions → Write；旁邊的 Customer authentication tokens 不用勾）"
step "Expiry date 設最長的一年（預設 90 天）。Rotatable 不用開。"
step "按 Save，複製 key（只會顯示一次，開頭是 pdl_sdbx_apikey_）。"
while :; do
  ask_secret PADDLE_API_KEY "貼上 API key（輸入不會顯示）："
  if [[ "$PADDLE_API_KEY" != pdl_sdbx_apikey_* ]]; then
    warn "開頭不是 pdl_sdbx_apikey_，可能貼到 live key 或 client-side token"; continue
  fi
  paddle_api GET /
  if ! api_ok || [[ -z "$(json_get 'data.caller.account')" ]]; then
    warn "Paddle 拒絕這把 key（HTTP $HTTP_STATUS $(json_get 'error.code')），請檢查後重貼"; continue
  fi
  missing=$(missing_permissions)
  [[ -z "$missing" ]] && break
  warn "這把 key 少了權限：$missing。回 Paddle 編輯這把 key 補勾後 Save，再貼一次"
done
write_env PADDLE_API_KEY "$PADDLE_API_KEY"
note "key 會在一年後過期；過期就回到這個頁面建一把新的，再重跑這個 wizard。"
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "前端用的 client-side token"
say "checkout 頁的 Paddle.js 用這個 token 初始化。它會出現在網頁原始碼裡，"
say "所以只能做前端的事，不算機密，但一樣只存在 repo 外的設定檔。"
open_url "$SANDBOX_DASHBOARD/settings/authentication"
step "點「Client-side tokens」分頁 → 「New client-side token」。"
step "Name：naruhodo-local-site；Description：本機 Astro checkout 頁用 → Save。"
step "按 token 旁邊的按鈕 → Copy（開頭是 test_）。"
while :; do
  ask PADDLE_CLIENT_TOKEN "貼上 client-side token："
  [[ "$PADDLE_CLIENT_TOKEN" == test_* ]] && break
  warn "sandbox 的 client-side token 開頭是 test_，請再貼一次"
done
write_env PADDLE_CLIENT_TOKEN "$PADDLE_CLIENT_TOKEN"
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "default payment link"
say "Paddle 規定：沒設 default payment link 就不能建立任何 transaction。"
say "它的值不重要：Worker 建立 transaction 時一律用 checkout.url 指定付款頁"
say "（本機是 $SITE_ORIGIN_LOCAL/zh-tw/checkout 或 /en/checkout），所以已經設過就不用改。"
open_url "$SANDBOX_DASHBOARD"
step "左側選單 Checkout → Checkout settings。"
step "「Default payment link」已經有值就略過；空的話填 https://$PRODUCT_DOMAIN/zh-tw/checkout → Save。"
note "程式不會讀這個值，所以不記錄；第 9 步建立 transaction 時會確認它有設定。"
pause "確認有值後按 Enter"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "產品與年繳 price（自動）"
say "用 API 建立產品「Naruhodo Hosted Translation」和一個 USD 20／年 的 price。"
say "金額是暫定值；之後要改價格就新增一個 price，不要修改已經有人訂閱的 price。"
if [[ -n "$(_existing PADDLE_PRICE_ID || true)" ]]; then
  PADDLE_PRODUCT_ID=$(_existing PADDLE_PRODUCT_ID); PADDLE_PRICE_ID=$(_existing PADDLE_PRICE_ID)
  note "已經建立過：$PADDLE_PRODUCT_ID / $PADDLE_PRICE_ID，略過。"
elif confirm "要建立產品與 price 嗎？"; then
  paddle_api POST /products '{"name":"Naruhodo Hosted Translation","tax_category":"standard","description":"Hosted translation for the Naruhodo Chrome extension (annual subscription)."}'
  api_ok || api_fail "create product"
  write_env PADDLE_PRODUCT_ID "$(json_get 'data.id')"
  paddle_api POST /prices "{\"product_id\":\"$PADDLE_PRODUCT_ID\",\"description\":\"Annual\",\"name\":\"Annual\",\"unit_price\":{\"amount\":\"2000\",\"currency_code\":\"USD\"},\"billing_cycle\":{\"interval\":\"year\",\"frequency\":1}}"
  api_ok || api_fail "create price"
  write_env PADDLE_PRICE_ID "$(json_get 'data.id')"
else
  warn "沒有 price 就無法建立 transaction；之後重跑這個 wizard 再建。"
fi
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "安裝 cloudflared"
say "Paddle 的 webhook 要送到一個公開網址；cloudflared 的 quick tunnel"
say "會把一個臨時的 https://xxx.trycloudflare.com 轉到本機的 wrangler dev（8787 port）。"
say "quick tunnel 不需要 Cloudflare 帳號，但每次啟動網址都會變，"
say "所以 scripts/paddle-tunnel.ts 會在啟動後用 API 把 webhook 網址改成新的。"
if CLOUDFLARED=$(find_cloudflared); then
  note "已安裝：$CLOUDFLARED"
elif confirm "用 winget 安裝 cloudflared 嗎？"; then
  winget install --id Cloudflare.cloudflared -e --accept-source-agreements
  CLOUDFLARED=$(find_cloudflared) || warn "裝好了但這個 shell 找不到；開新的 terminal 再跑 paddle-tunnel"
else
  SKIPPED+=("安裝 cloudflared：winget install --id Cloudflare.cloudflared")
fi
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "webhook destination 與 secret（自動）"
say "用 API 建立一個 notification destination，訂閱 Subscription 相關事件。"
say "建立時 Paddle 會回傳簽章用的 secret，直接存檔，不顯示在畫面上。"
say "網址先填正式網域；跑 paddle-tunnel 時會換成當下的 tunnel 網址。"
if [[ -n "$(_existing PADDLE_NOTIFICATION_SETTING_ID || true)" ]]; then
  PADDLE_NOTIFICATION_SETTING_ID=$(_existing PADDLE_NOTIFICATION_SETTING_ID)
  note "已經建立過：$PADDLE_NOTIFICATION_SETTING_ID，略過。"
elif confirm "要建立 webhook destination 嗎？"; then
  paddle_api POST /notification-settings "{\"description\":\"naruhodo local wrangler dev (via tunnel)\",\"type\":\"url\",\"destination\":\"https://api.$PRODUCT_DOMAIN$WEBHOOK_PATH\",\"subscribed_events\":$WEBHOOK_EVENTS,\"traffic_source\":\"all\"}"
  api_ok || api_fail "create notification setting"
  write_env PADDLE_NOTIFICATION_SETTING_ID "$(json_get 'data.id')"
  write_env PADDLE_WEBHOOK_SECRET "$(json_get 'data.endpoint_secret_key')"
fi
note "traffic_source 設成 all：真實事件和後台的模擬事件都會送過來。"
pause

# ── 9 ────────────────────────────────────────────────────────────────────
stage "驗證：建立一筆 transaction（自動）"
say "模擬 Worker 會做的事：建立 transaction、custom_data 放 account id，拿回 checkout.url。"
say "不會付款；這筆 transaction 會停在 ready 狀態，放著不管就好。"
[[ -n "${PADDLE_PRICE_ID:-}" ]] || { warn "還沒有 price（第 6 步），重跑 wizard 補上"; exit 1; }
paddle_api POST /transactions "{\"items\":[{\"price_id\":\"$PADDLE_PRICE_ID\",\"quantity\":1}],\"custom_data\":{\"account_id\":\"wizard-check\"}}"
api_ok || api_fail "create transaction"
step "Paddle 回的 checkout.url（default payment link）：$(json_get 'data.checkout.url')"
step "Worker 實際回給外掛的網址：$SITE_ORIGIN_LOCAL/zh-tw/checkout?_ptxn=$(json_get 'data.id')"
note "transaction 的 checkout.url 只能覆寫成 Paddle 核准過的網域（sandbox 也一樣，localhost 不行），"
note "所以 Worker 不用 checkout.url，而是用 transaction id 自己組網址；載入 Paddle.js 的頁面"
note "看到 _ptxn 就會打開那筆 transaction。sandbox 的 Paddle.js 在 localhost 上可以正常打開。"
pause

# ── 10 ───────────────────────────────────────────────────────────────────
stage "驗證：tunnel 收得到 webhook"
[[ -n "${PADDLE_NOTIFICATION_SETTING_ID:-}" ]] || { warn "還沒有 webhook destination（第 8 步），重跑 wizard 補上"; exit 1; }
say "開另一個 terminal，在 repo 根目錄執行："
say ""
say "    node scripts/paddle-tunnel.ts --echo"
say ""
say "--echo 會在 8787 port 開一個只驗簽章、印出事件的小伺服器（Worker 還沒寫好時用）。"
say "等它印出「webhook destination → https://…trycloudflare.com/webhooks/paddle」。"
pause "看到那行後按 Enter，wizard 會請 Paddle 送一個模擬的 subscription.created"
paddle_api POST /simulations "{\"notification_setting_id\":\"$PADDLE_NOTIFICATION_SETTING_ID\",\"type\":\"subscription.created\",\"name\":\"wizard tunnel check\"}"
api_ok || api_fail "create simulation"
SIMULATION_ID=$(json_get 'data.id')
paddle_api POST "/simulations/$SIMULATION_ID/runs"
api_ok || api_fail "run simulation"
say "已送出。幾秒內另一個 terminal 應該印出「✓ signature ok  subscription.created」。"
if ! confirm "有看到嗎？"; then
  SKIPPED+=("webhook 沒收到：檢查 paddle-tunnel 的輸出，以及後台 Developer tools → Notifications 的送出紀錄")
fi
say "測完可以在另一個 terminal 按 Ctrl-C 關掉 tunnel。"
pause

finish
say "設定檔：$ENV_FILE（不要 commit、不要貼到 issue）"
say "本機 checkout 頁：$SITE_ORIGIN_LOCAL/zh-tw/checkout、$SITE_ORIGIN_LOCAL/en/checkout"
say "本機 webhook：http://localhost:8787$WEBHOOK_PATH（paddle-tunnel 轉進來）"
}

run_wizard "$@"; exit
